/* Yakuniy testlar (o'zbekcha): har biri 50 savol, batafsil izohlar bilan. Format: [savol, [to'g'ri, noto'g'ri, noto'g'ri, noto'g'ri], izoh]. */
Object.assign(QD_ALL.uz, {
"exam-1": [
 ["Clopos'ning bosh ofisi qayerda va kompaniya qachon tashkil etilgan?",["Boku, 2018","Toshkent, 2015","Istanbul, 2020","Olmaota, 2019"],"Clopos 2018-yilda Bokuda tashkil topgan va hozir O'zbekiston, Ozarbayjon, Qozog'iston, Gruziya, Turkiya va boshqa davlatlarda ishlaydi. Boshqa variantlar — boshqa shaharlar va yillar."],
 ["«Bulutli» tizim nimani anglatadi?",["Ma'lumotlar serverlarda saqlanadi va internetga ulangan istalgan qurilmadan ochiladi","Dastur faqat internetsiz ishlaydi","Dasturni har bir kompyuterga qo'lda o'rnatish kerak","Ma'lumotlar faqat kassada saqlanadi"],"Bulutli tizim ma'lumotlarni internetdagi serverlarda saqlaydi, shuning uchun ega savdolarni istalgan qurilmadan ko'radi. Dasturni har bir kompyuterga qo'lda o'rnatish shart emas, ma'lumotlar bitta kassaga bog'lanmagan."],
 ["Bek-ofis terminaldan nimasi bilan farq qiladi?",["Bek-ofis — egasining boshqaruv kabineti, terminal — xodimning ish joyi","Bular bir xil","Terminal faqat ombor uchun","Bek-ofis oshxonada turadi"],"Bek-ofis — ega hisobotlarni ko'radigan va tizimni sozlaydigan veb-kabinet. Terminal — xodimlar buyurtma qabul qiladigan kassa, ofitsiant yoki kuryer telefoni. Bular bitta tizimning turli qismlari."],
 ["Clopos tariflari qancha turadi?",["Start — 29 $, Standart — 59 $ oyiga","Start — 19 $, Standart — 49 $","Standart — 45 $, Premium — 99 $","Bitta tarif — yiliga 99 $"],"Amaldagi narxlar: Start — 29 $, Standart — 59 $ oyiga. Demoda 45 $ ko'rsatilgan — bu o'quv ma'lumotlari. Boshqa tariflarni (Premium, yillik) mijozlarga aytmaymiz."],
 ["Quyidagi modullardan qaysi biri bepul?",["Stop-list","KDS","Sadoqat","Band qilish"],"Stop-list bepul: u tugagan taomlar sotuvini to'xtatadi. KDS (9 $), Loyallik (19 $) va Bron qilish (19 $) — pullik modullar."],
 ["«Band qilish» moduli qancha turadi?",["Oyiga 19 $","Oyiga 9 $","Oyiga 5 $","Bepul"],"Bron qilish oyiga 19 $ turadi — Loyallik va Yandex Eats bilan bir xil. KDS, QR-menyu va Kampaniyalar 9 $ dan, Sharhlar, Prays-listlar va Motivatsiya dasturi 5 $ dan."],
 ["Start tarifidagi mijoz QR-menyu va Sharhlar modullarini uladi. Endi uning oylik to'lovi nimadan iborat?",["Start tarifi va ikki pullik modul narxi","Faqat Start tarifi","Faqat modullar narxi","Standart tarifi, chunki modullar faqat unda mavjud"],"Mijozning oylik to'lovi — tarif va barcha ulangan pullik modullar. QR-menyu (9 $) va Sharhlar (5 $) pullik, shuning uchun to'lov oshdi. Buning uchun Standartga o'tish shart emas."],
 ["Mijoz Start tarifidan Standartga o'tdi. MRR bilan nima bo'ldi?",["MRR o'sdi — bu Expansion","MRR kamaydi — bu Contraction","MRR o'zgarmadi","Bu New MRR, chunki tarif yangi"],"Mijoz o'sha, lekin ko'proq to'lay boshladi: Standart Start'dan qimmat. Bu Expansion. New MRR — faqat butunlay yangi mijozlar."],
 ["KDS va Yandex Eats ulangan Standart tarifidagi mijoz Clopos'dan ketdi. Kompaniya nimani yo'qotadi?",["Uning butun oylik to'lovini — tarif va ikkala modulni — keyingi har oyda","Faqat modullar narxini","Faqat bir oylik to'lovni","O'tgan oylar uchun to'lagan bo'lsa, hech narsa"],"Mijoz ketganda (Churn) kompaniya uning butun oylik to'lovini bir oyga emas, kelajakdagi barcha vaqtga yo'qotadi. Shuning uchun ushlab qolish juda qimmatli."],
 ["Obuna kompaniyasi uchun bitta mijozni yo'qotish nega bir oylik hisobda ko'ringanidan jiddiyroq?",["Kompaniya uning faqat joriy emas, kelajakdagi barcha oylar to'lovlarini yo'qotadi","Mijoz o'tgan oylar pulini qaytarib oladi","Kompaniya har bir ketgan mijoz uchun jarima to'laydi","Chunki mijoz darhol raqobatchiga o'tadi"],"Obuna modelida mijoz har oy to'laydi. Uni yo'qotib, kompaniya undan keladigan barcha kelajakdagi daromadni — uning LTV'sini yo'qotadi. O'tgan to'lovlar qaytarilmaydi."],
 ["Reglament Retention bo'limi vazifasini qanday belgilaydi?",["Ketishning oldini olish, LTV'ni oshirish va mijozlarni qaytarish uchun faol, xavf ostidagi va expired mijozlar bilan tizimli ishlash","Yangi muassasalarga Clopos sotish","Uskunalarni texnik qo'llab-quvvatlash","Ijtimoiy tarmoqlarda reklama yuritish"],"Reglament Retention'ni ushlab qolish, LTV'ni oshirish va qaytarish uchun faol, xavf ostidagi va expired mijozlar bilan tizimli ish deb ta'riflaydi. Yangilarga sotish, texnik qo'llab-quvvatlash va reklama — boshqa bo'limlar vazifasi."],
 ["Retention qaysi bo'limlar bilan hamkorlik qiladi?",["Technical Support, Sales, Key Account, Marketing (SMM)","Faqat buxgalteriya bilan","Faqat sotuv bo'limi bilan","Hech kim bilan"],"Retention texnik savollarni Technical Support'ga topshiradi, statuslarni Sales bilan aniqlaydi, yirik mijozlar bo'yicha Key Account bilan, kommunikatsiyalar bo'yicha Marketing bilan ishlaydi. Bo'lim yolg'iz ishlay olmaydi."],
 ["Reglamentga ko'ra Retention bo'limi ishining asosiy tamoyili:",["Mijoz bilan har bir muloqot CRM'da qayd etiladi va mantiqiy natijagacha yetkaziladi","Kuniga imkon qadar ko'p mijozga qo'ng'iroq qilish","Avval sotish, keyin muammolarni hal qilish","Faqat kiruvchi murojaatlar bilan ishlash"],"Asosiy tamoyil: hamma narsa CRM'da qayd etiladi va natijaga yetkaziladi. Qo'ng'iroqlar soni o'z-o'zidan maqsad emas, faqat kiruvchi murojaatlar bilan ishlash esa xavfni oldindan ko'rishga imkon bermaydi."],
 ["Quyidagilardan qaysi biri Retention bo'limi vazifasiga KIRMAYDI?",["Mijozning buxgalteriya hisobini yuritish","Expired mijozlarni qaytarish","Fikr-mulohazalarni yig'ish va qayd etish","Texnik muammolarni qo'llab-quvvatlashga topshirish"],"Mijoz buxgalteriyasi — bizning ishimiz emas. Expired mijozlarni qaytarish, fikr-mulohaza yig'ish va texnik muammolarni topshirish — reglament bo'yicha bo'limning bevosita vazifalari."],
 ["Expired mijoz kim?",["To'langan xizmat muddati tugagan mijoz","Shu oyda ulangan mijoz","MRR'i eng katta mijoz","Key Account xizmat ko'rsatadigan mijoz"],"Expired — mijozning to'langan muddati tugagan va u obunani uzaytirmagan. Sababini bilish muhim: ta'mir, mavsum, tizimdagi muammolar yoki shunchaki unutgan."],
 ["Xavf ostidagi mijoz kim?",["Ketish belgilari bor mijoz: kam kiradi, shikoyat qiladi, javob bermaydi, modullarni o'chiradi","Har qanday yangi mijoz","Start tarifidagi mijoz","Bitta filialli mijoz"],"Xavf ostidagi mijoz hali to'laydi, lekin xavotirli signallar bor: tizimga kirmaydi, shikoyat qiladi, javob bermaydi, modullarni o'chiradi. Yangi mijoz, Start tarifi yoki bitta filial o'z-o'zidan xavf emas."],
 ["MRR nima?",["Barcha obunalardan muntazam oylik tushum: tariflar va pullik modullar","Restoranning oylik tushumi","Integratsiyalar uchun bir martalik to'lovlar","Mijozlar soni"],"MRR — mijozlar Clopos'ga har oy to'laydigan pul: tariflar va pullik modullar. Bu restoranlar tushumi ham, bir martalik to'lovlar ham, mijozlar soni ham emas."],
 ["New MRR qayerdan paydo bo'ladi?",["Sotuv bo'limi ulagan yangi mijozlardan","Modul ulagan mijozlardan","Qaytgan expired mijozlardan","Tarif oshirilishidan"],"New MRR faqat sotuv olib kelgan yangi mijozlardan keladi. Modul ulash va tarifni oshirish — Expansion, qaytgan mijoz — Reactivation."],
 ["Quyidagilardan qaysi biri Expansion MRR?",["Mijoz Clopos'da ikkinchi filial ochdi va KDS uladi","Yangi kafe Clopos'ga obuna bo'ldi","Mijoz Kampaniyalarni o'chirdi","Mijoz to'lashni to'xtatdi"],"Mavjud mijoz filial ochib, KDS uladi — ko'proq to'laydi, bu Expansion. Yangi kafe — New MRR, modulni o'chirish — Contraction, to'lovni to'xtatish — Churn."],
 ["Quyidagilardan qaysi biri Contraction MRR?",["Mijoz Standartdan Startga o'tdi","Mijoz Band qilishni uladi","Mijoz tanaffusdan keyin qaytdi","Mijoz yangi nuqta ochdi"],"Mijoz qoldi, lekin arzonroq tarifga o'tdi — to'lov kamaydi, bu Contraction. Ulash va yangi nuqta — Expansion, qaytish — Reactivation."],
 ["Churn MRR nima?",["Ketgan mijozlar sababli yo'qotilgan MRR","Yangi mijozlardan MRR","Obunaga chegirmalar","Modullardan MRR"],"Churn MRR — ketgan mijozlar tufayli yo'qotilgan tushum. Ketishning oldini olish — Retention'ning asosiy vazifasi."],
 ["Reactivation MRR nima?",["Avval ketgan yoki expired bo'lgan, qaytgan mijozlardan MRR","Yangi mijozlardan MRR","Modullar hisobiga o'sish","Uzaytirishdagi chegirma"],"Reactivation — ketgan yoki expired bo'lib, qaytgan mijozlardan keladigan pul. Bunday mijozlarni qaytarish — bo'limning bevosita vazifasi."],
 ["Net New MRR nimani ko'rsatadi?",["Barcha kirim va yo'qotishlarni hisobga olganda MRR bir oyda qanchaga o'sgani yoki kamaygani","Faqat yangi mijozlar MRR'ini","Yangi mijozlar sonini","Restoranlarning oylik tushumini"],"Net New MRR qo'shilgan hamma narsani (yangi mijozlar, o'sish, qaytishlar) qo'shib, ketgan hamma narsani (qisqarish va ketish) ayiradi. Manfiy bo'lsa — baza qisqarmoqda."],
 ["Oylik Net New MRR manfiy chiqdi. Bu nimani anglatadi?",["Ketish va qisqarishdan yo'qotishlar yangi mijozlar, o'sish va qaytishlardan kelgan kirimdan katta","Ko'p yangi mijoz keldi","Barcha mijozlar modul uladi","Hisobotdagi xato, bunday bo'lmaydi"],"Manfiy Net New MRR oy oxiridagi MRR boshidagidan kamligini bildiradi. Bu ushlab qolishni kuchaytirish kerakligi haqida signal."],
 ["Oylik NRR — 96%. Buni qanday tushunish kerak?",["Mavjud mijozlar birgalikda oy boshidagidan kamroq to'lay boshladi","Mijozlarning 96% i ketdi","96 ta yangi mijoz keldi","Baza 96% ga o'sdi"],"NRR 100% dan past bo'lsa, ketish va qisqarishdan yo'qotishlar mavjud mijozlardan o'sishdan katta. Yangi sotuvlarsiz MRR kamayib borardi."],
 ["Nega NRR'da yangi mijozlar hisobga olinmaydi?",["NRR mavjud bazadan tushum qanday o'zgarishini ko'rsatadi","Yangi mijozlar juda kam","Shunday hisoblash osonroq","Yangi mijozlar birinchi oy to'lamaydi"],"NRR faqat mavjud bazani o'lchaydi: o'sish, qisqarish va ketish. Yangi mijozlar qo'shilsa, yaxshi sotuv yomon ushlab qolishni yashiradi."],
 ["Mijozlar bo'yicha ketish (churn rate) nimani ko'rsatadi?",["Davr mobaynida mijozlarning qancha qismi ketganini","Nechta yangi mijoz kelganini","Nechta modul ulanganini","Mijozning o'rtacha to'lovini"],"Mijozlar bo'yicha churn rate — davr boshidagi mijozlardan ketganlar ulushi. U qancha past bo'lsa, ushlab qolish shuncha yaxshi ishlaydi."],
 ["Tushum bo'yicha ketish (MRR bo'yicha churn) mijozlar bo'yicha ketishdan nimasi bilan farq qiladi?",["U ketgan mijozlar ulushini emas, yo'qotilgan pul ulushini ko'rsatadi","Bu bir xil narsa","U faqat yangi mijozlarni ko'rsatadi","U faqat yirik mijozlar uchun hisoblanadi"],"Kichik mijozlar ketgan bo'lsa, mijozlar bo'yicha ketish yuqori, tushum bo'yicha esa kichik bo'lishi mumkin va aksincha. Shuning uchun ikkala metrikaga qaraladi."],
 ["ARPU nima?",["Bitta mijozning o'rtacha oylik to'lovi","Restoranning o'rtacha cheki","Faol mijozlar soni","Kompaniyaning yillik tushumi"],"ARPU — bitta Clopos mijozining o'rtacha oylik to'lovi. Bu restoranning o'rtacha cheki ham, mijozlar soni ham emas."],
 ["Retention ARPU'ni qanday oshirishi mumkin?",["Mijozlarga kerak bo'lganda foydali modullar ulash va yuqoriroq tarifga o'tishga yordam berib","Barcha mijozlarga chegirma berib","Mijozlar modullarini o'chirib","Faqat kichik mijozlarni jalb qilib"],"ARPU — mijozning o'rtacha to'lovi. Mijozlar ko'proq foyda olib, buning uchun to'laganda o'sadi. Chegirma va o'chirishlar uni kamaytiradi."],
 ["Mijozni ushlab qolish LTV'ga qanday ta'sir qiladi?",["Mijoz qancha uzoq qolsa, butun davr ichida shuncha ko'p keltiradi — LTV o'sadi","LTV muddatga bog'liq emas","LTV kamayadi","LTV faqat tarifga bog'liq"],"LTV — mijoz butun davr mobaynida qancha olib keladi. U qancha uzoq qolsa, shuncha ko'p oy to'laydi — LTV o'sadi. LTV tarifga ham bog'liq, lekin faqat unga emas."],
 ["Mijoz ko'proq funksiyadan foydalansa, uning LTV'si nega o'sadi?",["U ko'proq foyda oladi, uzoqroq qoladi va oyiga ko'proq to'laydi","Funksiyalar bepul va hech narsani o'zgartirmaydi","LTV faqat ulanish sanasiga bog'liq","Chunki mijoz texnik qo'llab-quvvatlashga tez-tez qo'ng'iroq qiladi"],"LTV ikki narsaga bog'liq: oylik to'lov hajmi va mijozning qolish muddati. Foydali funksiyalar ikkalasini ham oshiradi."],
 ["Retention bo'limining oylik hisobotiga nima kiradi?",["Dinamika bilan % churn va NRR, ushlab qolingan mijozlar, integratsiyalar, xavf ostidagi mijozlar, fidbek va ketish sabablari","Faqat qo'ng'iroqlar soni","Faqat yangi mijozlar ro'yxati","Faqat restoranlar tushumi"],"Bo'limning oylik hisoboti baza sog'lig'ini ko'rsatadi: dinamikadagi ketish va NRR, ushlab qolingan mijozlar, integratsiyalar, xavf ostidagi mijozlar, fikr-mulohaza va ketish sabablari. Restoranlar tushumi kirmaydi."],
 ["Retention'ning qaysi vazifasi oylik uchrashuvlar (MBR) bilan bog'liq?",["Mijozlarni 2 oy ichida MBR'ga tayyorlash","Ega o'rniga MBR o'tkazish","MBR'ni bekor qilish","MBR faqat Sales'ga tegishli"],"Retention ikki oy davomida mijozni MBR'ga tayyorlaydi: faktlar, muammolar va takliflarni yig'adi. Uchrashuv mijoz o'rniga emas, u bilan birga o'tkaziladi."],
 ["Mijoz: «Mehmonlar kam». Bu biznes-assistent yordamining qaysi darajasi?",["Uchinchi: Clopos'dan tashqaridagi muammo — Clopos ma'lumotlari asosida xaritalardagi sharhlar va aksiyalarni maslahat berish","Birinchi: tugmalar haqidagi savol","Ikkinchi: modulni sozlash","Bizning vazifamiz emas"],"«Mehmon kam» — dasturdan tashqari biznes vazifasi: xaritalardagi sharhlar, bo'sh soatlarga aksiyalar, doimiy mehmonlar bilan ishlash. Clopos yechim uchun ma'lumot beradi. Bu yordamning uchinchi darajasi."],
 ["Muassasaning kunlik tushumi oshdi, cheklar soni esa o'zgarmadi. Nima bo'ldi?",["O'rtacha chek o'sdi — mehmonlar ko'proq sarflay boshladi","Ko'proq mehmon keldi","Tannarx pasaydi","Hisobdan chiqarishlar oshdi"],"Tushum = cheklar × o'rtacha chek. Cheklar o'shancha, tushum esa yuqori bo'lsa, har bir mehmon o'rtacha ko'proq sarflaydi."],
 ["Taom tannarxi deyarli narxiga teng. Bu ega uchun nimani anglatadi?",["Har bir sotuvdan ish haqi, ijara va foydaga deyarli hech narsa qolmaydi","Taom juda foydali","Porsiyani shoshilinch oshirish kerak","Bu barcha oshxona taomlari uchun normal"],"Yuqori fudkost narxning deyarli hammasi mahsulotlarga ketishini bildiradi. Texkarta va narxni tekshirish kerak. Oshxona taomlari uchun fudkost mo'ljali — 25–35%."],
 ["Clopos'dagi savdo ustamasi nimani ko'rsatadi?",["Narx tannarxdan qanchaga yuqoriligini","Taomni yetkazib berish narxini","Ofitsiant qancha olishini","Doimiy mehmonlar uchun chegirmani"],"Ustama narxni tannarx bilan solishtiradi. Manfiy ustama — mahsulotlar narxidan arzon sotyapmiz: bu deyarli doim texkartadagi xato."],
 ["Muassasaning qaysi xarajatlari prime cost deyiladi?",["Mahsulotlar va ish haqi birgalikda","Ijara va kommunal xizmatlar","Soliqlar va bank komissiyalari","Reklama va marketing"],"Prime cost — fudkost va ish haqi fondi, asosiy boshqariladigan xarajatlar. Mo'ljal odatda tushumning 60–65% idan oshmaydi."],
 ["Tushum kamaydi, o'rtacha chek o'sha-o'sha, cheklar kam. Avval nima qilish kerak?",["Trafik bilan shug'ullanish: soat va kunlar bo'yicha savdo, sharhlar, raqobatchilar","Tannarxni qayta hisoblash","Tarifni almashtirish","Modullarni o'chirish"],"O'rtacha chek o'zgarmagan, cheklar esa kam bo'lsa — muammo trafikda. Soat va kunlar bo'yicha savdo, sharhlar, raqobatchilarni ko'rish kerak. Tannarx, tarif va modullar mehmonlar soniga ta'sir qilmaydi."],
 ["O'rtacha chek pasaydi, mehmonlar soni o'sha-o'sha. Clopos orqali nima yordam beradi?",["Modifikatorlar, menyu tahlili, ofitsiantlar motivatsiya dasturi","Stop-list","Ombor ko'chirishlari","Inkassatsiya"],"Mehmonlar o'shancha, lekin kamroq sarflasa, qo'shimcha sotuv yordam beradi: modifikatorlar, menyu tahlili, ofitsiantlar motivatsiyasi. Stop-list, ko'chirishlar va inkassatsiyaning o'rtacha chekka aloqasi yo'q."],
 ["Taom ham mashhur, ham foydali. U qanday ataladi va nima qilish kerak?",["Yulduz: sifatni saqlash va menyuda ajratib ko'rsatish","It: olib tashlash","Jumboq: targ'ib qilish","Ishchi ot: narxni oshirish"],"Yulduz — mashhur va foydali taom. Uni asraydilar: sifatni saqlaydilar va menyuda ajratib ko'rsatadilar. Itni olib tashlaydilar, jumboqni targ'ib qiladilar, ishchi otning tannarxini qayta ko'rib chiqadilar."],
 ["Qaysi taom «jumboq» deb ataladi?",["Foydali, lekin kam buyurtma qilinadigan","Mashhur, lekin kam foydali","Mashhur emas va kam foydali","Eng qimmat"],"Jumboq — foydali, lekin kam buyurtma qilinadigan taom. Uni targ'ib qilish kerak. Mashhur kam foydali — ishchi ot, mashhur emas va kam foydali — it."],
 ["Menyudagi «it» bilan nima qilish kerak?",["Almashtirish yoki olib tashlash","Asosiy taomga aylantirish","Narxni ikki baravar oshirish","Doimiy aksiyaga qo'yish"],"It menyu va omborda joy egallaydi, lekin deyarli sotilmaydi va kam keltiradi. Uni almashtiradilar yoki olib tashlaydilar. Narxni oshirish yoki doimiy aksiya vaziyatni tuzatmaydi."],
 ["Nega yetkazib berish uchun ko'pincha alohida narx qo'yiladi?",["Xizmatning 15–30% lik komissiyasi marjani yeydi","Buni soliq idorasi talab qiladi","Mehmonlarga arzonroq bo'lishi uchun","Aks holda kassa ishlamaydi"],"Yetkazib berish xizmati buyurtmadan 15–30% oladi, mahsulotlar esa shuncha turadi. Alohida narxlarsiz muassasa minusda ishlashi mumkin. Clopos'da buning uchun Prays-listlar moduli bor."],
 ["Ertalab mehmon oqimi ko'p bo'lgan qahvaxona uchun eng muhimi nima?",["Xizmat tezligi va qo'shimcha savdo","Stollar aylanishi","Murakkab menyu","Yetkazib berish ulushi"],"Ertalab qahvaxona mehmonlari shoshadi: tezlik va qo'shimcha sotuv (qahvaga pishiriq) muhim. Stollar aylanishi olib ketish qahvaxonasiga emas, restoranga muhim."],
 ["Milliy taomlar muassasasiga Clopos'da yarim tayyor mahsulotlar nima uchun kerak?",["Katta zagotovkalarni (xamir, lag'mon) va ularning chiqishini aniq hisobga olish uchun","Menyu chop etish uchun","Band qilish uchun","Ish haqi to'lash uchun"],"Yarim tayyor mahsulotlar katta tayyorlovlarni — xamir, lag'mon — va ularning chiqishini hisobga olish imkonini beradi. Busiz haqiqatda qancha mahsulot ketayotgani ko'rinmaydi. Menyu chop etish, bron va maosh — boshqa bo'limlar."],
 ["Muassasalar tarmog'i uchun eng muhimi nima?",["Nuqtalarni o'zaro solishtirish va yagona sifatni saqlash","Barcha nuqtalarga bitta terminal","Hisobotlarni o'chirish","Omborsiz ishlash"],"Tarmoq qaysi nuqta yomonroq ishlayotganini ko'rishi va yagona standartlarni saqlashi kerak. Clopos'da buning uchun filiallar hisobotlari va AI Yordamchida solishtirish bor."],
 ["Mijoz «qimmat» deydi. Odatda buning ortida nima turadi?",["Mijoz tizimdan foydani ko'rmayapti","Mijozda pul yetishmaydi","Mijozga interfeys yoqmaydi","Mijoz ko'proq modul xohlaydi"],"Ko'pincha «qimmat» «foydasini ko'rmayapman» degani. Shuning uchun darhol narxni tushirish emas, mijoz nimadan foydalanishini aniqlab, uning ma'lumotlarida qadrini ko'rsatish kerak."],
 ["Biznes-assistent texnik qo'llab-quvvatlashdan nimasi bilan farq qiladi?",["Clopos funksiyalarini mijozning puli va vazifalari bilan bog'laydi","Hech narsasi bilan","Faqat yirik mijozlar bilan ishlaydi","Faqat modul sotadi"],"Biznes-yordamchi funksiyalarni mijozning puli va vazifalari bilan bog'laydi. Texnik qo'llab-quvvatlash dasturda qanday qilishni tushuntiradi. Modullar sotish — vositalardan faqat biri."]
],
"exam-2": [
 ["Ega bugungi tushum, o'rtacha chek va cheklar sonini qayerda ko'radi?",["Аналитика → Новая Панель Управления","Склад → Остатки","Меню → Товары","Настройки → Чеки"],"Yangi boshqaruv paneli — savdo haqidagi suhbat uchun birinchi nuqta: tanlangan davr uchun tushum, o'rtacha chek, cheklar, mehmonlar, qaytarishlar. Boshqa bo'limlar boshqa ma'lumotlarni ko'rsatadi."],
 ["Filiallar tushumini qanday solishtirish mumkin?",["Аналитика → Отчеты филиалов","Финансы → Категории","Маркетинг → Клиенты","Склад → Поставщики"],"Filiallar hisobotlari har bir nuqtani alohida ko'rsatadi, shuning uchun qaysi biri ortda qolayotgani darhol ko'rinadi. Demoda uchta filial: Uzb, Uzb 2, Tex podderjka."],
 ["Aniq chek bo'yicha barcha amallar — kim qo'shdi, o'chirdi, yopdi — qayerda?",["Аналитика → История","Продажи → Типы продаж","Финансы → Счета","Меню → Отделы"],"Tarix chek bo'yicha har bir harakatni yozadi: kim qo'shgan, o'chirgan, yopgan. «Shubhali harakatlar» filtri o'chirish, bekor qilish va chegirmalarni ajratadi."],
 ["Tannarx va foyda bilan har bir tovar bo'yicha savdo hisoboti qayerda?",["Аналитика → Отчеты","Склад → Остатки","Финансы → Операции","Продажи → Заказы"],"«Аналитика → Отчеты» da tovarlar bo'yicha savdo hisoboti bor: har bir pozitsiya bo'yicha miqdor, tushum, tannarx va foyda. Bu menyu tahlilining asosi."],
 ["AI Assistent (Beta) nima qila oladi?",["Savdo, xodimlar va tovarlar haqidagi savollarga javob beradi, masalan «Сравните эту неделю с прошлой»","Menyudagi narxlarni o'zi o'zgartiradi","To'lov qabul qiladi","Mijozlarga qo'ng'iroq qiladi"],"AI Yordamchi savdo, xodimlar va tovarlar haqidagi savollarga rus va o'zbek tilida oddiy so'zlar bilan javob beradi. Masalan: «Сравните эту неделю с прошлой». U kassir o'rnini bosmaydi va sozlamalarni o'zgartirmaydi."],
 ["Mehmonlarga qaytarilgan pullarni qayerda ko'rish mumkin?",["Продажи → Возврат товара","Склад → Возврат товаров","Финансы → Заработная плата","Маркетинг → Отзывы"],"«Продажи → Возврат товара» — mehmonlarga qaytarishlar. «Склад → Возврат товаров» — mahsulotlarni yetkazib beruvchiga qaytarish. Ularni adashtirish oson."],
 ["Mehmon, sana, stol va mehmonlar soni ko'rsatilgan bandlar ro'yxati qayerda?",["Продажи → Бронирования","Настройки → Управление столами","Маркетинг → Клиенты","Сотрудник → Посещаемость"],"Bronlarda mehmon, telefon, sana, stol, mehmonlar soni va manba saqlanadi. Kengaytirilgan funksiyalar (depozit, QR orqali bron) uchun pullik «Бронирование» moduli bor."],
 ["Muassasa Payme qabul qila boshladi. To'lov usulini qayerga qo'shish kerak?",["Продажи → Способы оплаты","Меню → Модификаторы","Сотрудник → Должности","Склад → Создание тары"],"To'lov usuli «Продажи → Способы оплаты» da qo'shiladi va Moliyadagi hisobga bog'lanadi. Noto'g'ri hisobga bog'lansa, hisobotlarda pul boshqa joyda bo'lib qoladi."],
 ["Yandex Eats va Uzum Tezkor'dagi narxlar zaldagidan yuqori bo'lishi kerak. Nimadan foydalaniladi?",["Prays-listlar moduli: Tovarlarda platformalar uchun narx ustunlari paydo bo'ladi","Modifikatorlar","Kampaniyalar","Hisobdan chiqarishlar"],"Prays-listlar moduli yetkazib berish platformalari yoki vaqt bo'yicha alohida narxlar berish imkonini beradi. Xizmat komissiya olganda marjani himoya qiladi."],
 ["Yarim tayyor mahsulot nima?",["O'z tarkibiga ega bo'lib, boshqa taomlarga kiradigan zagotovka","Sotib olingan tovar","To'lov usuli","Lavozim"],"Yarim tayyor mahsulot — boshqa taomlar tarkibiga kiradigan, o'z tarkibiga ega tayyorlov (demoda: Lag'mon, Xamir). Shunda ombor aniq hisobdan chiqariladi."],
 ["Xom ashyoning o'lchov birligi va tannarxi qayerda belgilanadi?",["Меню → Ингредиент","Склад → Поставщики","Финансы → Категории","Настройки → Общие"],"Xomashyoning o'lchov birligi va tannarxi ingredient kartochkasida belgilanadi. Narx ingredient yuritiladigan birlik uchun ko'rsatilishi kerak."],
 ["Tuz ingredienti grammda yuritiladi, tannarx esa kilogramm uchun kabi 15 000 deb kiritilgan. Oqibati?",["Tuzli taomlar tannarxi 1000 baravar oshib ketadi","Tannarx kamayadi","Tuz menyudan yo'qoladi","Kassa ishlamay qoladi"],"Ingredient grammda yuritilib, narxi kilogramm uchundek ko'rsatilsa, u ishlatiladigan barcha taomlar tannarxi 1000 marta oshadi. Kassa ishlaydi, lekin foyda hisobotlari noto'g'ri bo'ladi."],
 ["Kassada taom tugmalari joylashuvi qayerda belgilanadi?",["Меню → Макет меню","Меню → Отделы","Настройки → Чеки","Устройства → Терминалы"],"Menyu maketi kassadagi taom tugmalari joylashuvini belgilaydi. Qulay maket pik soatlarda kassir ishini tezlashtiradi."],
 ["«Сопоставление товаров» (Tovarlarni moslashtirish) nima uchun kerak?",["Clopos pozitsiyalarini tashqi tizimlardagi (masalan, agregatorlardagi) pozitsiyalar bilan bog'lash","Raqobatchilar narxlarini solishtirish","Ikki omborni birlashtirish","Xodimlarni ko'chirish"],"Tovarlarni moslashtirish Clopos pozitsiyalarini tashqi tizimlardagi, masalan yetkazib berish xizmatlaridagi pozitsiyalar bilan bog'laydi. Bu integratsiyalar to'g'ri ishlashi uchun kerak."],
 ["Zallar, stollar soni va zal xizmat haqi qayerda sozlanadi?",["Настройки → Управление столами","Продажи → Типы продаж","QR-меню → Настройки","Склад → Склад"],"«Stollarni boshqarish»da zallar, stollar va har bir zal uchun xizmat haqi sozlanadi. Xizmat haqi uchun yana bir joy — «Savdo turlari»."],
 ["Stoldan buyurtma va «Hisobni so'rash» tugmasi qayerda yoqiladi?",["QR-меню → Настройки","Настройки → Терминал","Маркетинг → Кампании","Модули → Отзывы"],"Stoldan buyurtma, «Пригласить официанта» va «Попросить счёт» QR-menyu sozlamalarida yoqiladi. U yerda har bir stol uchun QR-kodlar ham bor."],
 ["Cheklarni avtomatik chop etish, yaxlitlash va chekni soliq idorasiga yuborish qayerda sozlanadi?",["Настройки → Терминал","Настройки → Общие","Финансы → Счета","Меню → Категории"],"Kassa xatti-harakati — avtochop etish, yaxlitlash, chekni soliqqa yuborish, bitta chekni bloklash — «Настройки → Терминал» da sozlanadi."],
 ["Chek ko'rinishi (konstruktor) qayerda o'zgartiriladi?",["Настройки → Чеки","Продажи → Чеки","Меню → Макет меню","Аналитика → Налоги"],"Chek, hisob va boshqa hujjatlarning ko'rinishi «Настройки → Чеки» dagi konstruktorda o'zgartiriladi."],
 ["Yetkazib beruvchidan tovar qayerda qabul qilinadi?",["Склад → Поступление товаров","Склад → Списания","Финансы → Денежный поток","Меню → Ингредиент"],"Yetkazib beruvchidan kirim «Склад → Поступление товаров» da rasmiylashtiriladi: yetkazib beruvchi, ombor, summa, to'lov. Busiz qoldiqlar noto'g'ri bo'ladi."],
 ["Mijoz yetkazib beruvchiga qancha qarzdorligini qayerda ko'rish mumkin?",["Склад → Поставщики, «Баланс» ustuni","Финансы → Категории","Продажи → Чеки","Маркетинг → Группа клиентов"],"Yetkazib beruvchi oldidagi qarz «Склад → Поставщики» da, «Баланс» ustunida ko'rinadi. Bu egaga hisob-kitoblarni nazorat qilishga yordam beradi."],
 ["Tovar Bar omboridan Oshxonaga o'tkaziladi.",["Склад → Перемещения","Склад → Производство","Продажи → Заказы","Финансы → Операции"],"Ko'chirish mahsulotlarni omborlar orasida o'tkazadi: birining qoldig'i kamayadi, ikkinchisiniki — oshadi. Hisobdan chiqarish — o'tkazish emas, yo'qotish."],
 ["Xom ashyodan yarim tayyor mahsulot qayerda ishlab chiqariladi?",["Склад → Производство","Склад → Остатки","Меню → Модификаторы","Финансы → Операции"],"«Склад → Производство» yarim tayyor mahsulot chiqaradi: xomashyoni hisobdan chiqarib, tayyorlovni kirim qiladi. Shunda tayyorlovlar hisobi aniq qoladi."],
 ["Aniq mahsulot harakati tarixini qayerda ko'rish mumkin?",["Склад → Движение продукта / Отчет о действиях","Аналитика → История","Финансы → Операции","Маркетинг → Клиенты"],"Mahsulot harakati va harakatlar hisoboti pozitsiyaning butun tarixini ko'rsatadi: kirimlar, savdolar, hisobdan chiqarishlar, ko'chirishlar. Bu yo'qotishlarni izlashga yordam beradi."],
 ["Inventarizatsiyadagi «Стоимость разницы» (Farq qiymati) nimani ko'rsatadi?",["Haqiqiy va hisobdagi qoldiq orasidagi farq qancha turishini","Yetkazib beruvchi narxini","Cheklar bo'yicha chegirmani","Ish haqi summasini"],"Farq qiymati — haqiqat va hisob o'rtasidagi tafovut qancha pul turishi. Katta farq — texkartalar, kirimlar va hisobdan chiqarishlarni tekshirish uchun sabab."],
 ["Ombor sozlamalaridagi «hisobdan chiqarish ketma-ketligi» nima?",["Sotuvda mahsulot qaysi omborlardan chiqarilishi tartibi","Yetkazib beruvchilarga to'lov tartibi","Oshxonadagi buyurtmalar navbati","Smenalar jadvali"],"Hisobdan chiqarish ketma-ketligi — Clopos sotuvda mahsulotlarni qaysi omborlardan qanday tartibda hisobdan chiqarishi. Birinchi omborda mahsulot tugasa, keyingisidan olinadi."],
 ["Inkassatsiya nima?",["Pulni hisoblar o'rtasida o'tkazish, masalan kassadan seyfga","Chegirma","Mahsulotni hisobdan chiqarish","Ish haqi"],"Inkassatsiya — pulni hisoblar orasida o'tkazish, masalan kassadan seyfga. Bu xarajat emas. Kategoriyalar noto'g'ri sozlansa, foydani buzishi mumkin."],
 ["Daromad va xarajat moddalari qayerda belgilanadi?",["Финансы → Категории","Финансы → Счета","Меню → Категории","Склад → Склад"],"Daromad va xarajat moddalari «Финансы → Категории» da belgilanadi: ta'minot, kommunal xizmatlar, ish haqi va boshqalar. Bular menyu kategoriyalari emas."],
 ["Xodimlarning hisoblangan va to'langan ish haqi qayerda ko'rinadi?",["Финансы → Заработная плата","Сотрудник → Пользователи","Сотрудник → Посещаемость","Финансы → Счета"],"Hisoblangan va to'langan ish haqi va bonuslar «Финансы → Заработная плата» da ko'rinadi. Davomat faqat kelish va ketishni ko'rsatadi."],
 ["«Денежный поток» (Pul oqimi) hisoboti nimani ko'rsatadi?",["Bir oyda toifalar bo'yicha qancha pul kelgani va ketganini","Har bir taom bo'yicha foydani","Ombor qoldiqlarini","Davomatni"],"Pul oqimi oy davomida kategoriyalar bo'yicha qancha pul kelib-ketganini ko'rsatadi. U biznes foyda qildimi degan savolga javob bermaydi — buning uchun P&L bor."],
 ["P&L'da sof foyda qanday hisoblanadi?",["Tushum − tannarx − operatsion − boshqa xarajatlar","Tushum + xarajatlar","Faqat tushum minus soliqlar","Hisoblardagi qoldiq"],"Sof foyda = tushum − tannarx − operatsion xarajatlar − boshqa xarajatlar. Avval yalpi foyda, keyin operatsion, keyin sof foyda chiqadi."],
 ["Demo P&L'da 1,4 mln tushumda sof foyda −189 mln. Asosiy sabab?",["Kartoshka fri texkartasidagi birlik xatosi tufayli 118 mln tannarx","Mehmonlar kam","Soliqlar","Yuqori ish haqi"],"118 mln tannarx Kartoshka fri texkartasidagi birlik xatosidan paydo bo'lgan. Qo'shimcha ravishda xarajatlarga 62 mln inkassatsiya va 10,75 mln hisobdan chiqarishlar tushgan. Dastur to'g'ri hisoblaydi — noto'g'ri ma'lumotlar bo'yicha."],
 ["«Сотрудник → Должности» bo'limida nima sozlanadi?",["Bek-ofis va terminalga kirish, rol huquqlari","Taomlar narxi","Yetkazib beruvchilar","Zallar"],"Lavozimlarda bek-ofis va terminalga kirish va huquqlar belgilanadi: chegirma, bekor qilish, o'chirish. Bu xodimlarni nazorat qilishning asosiy vositasi."],
 ["Xodim terminalga qanday kiradi?",["«Сотрудник → Пользователи» dagi PIN-kod bilan","Telefon raqami bilan","Egasining pochtasi bilan","Kirishsiz"],"Xodim terminalga shaxsiy PIN-kod bilan kiradi. Shuning uchun hisobotlardagi har bir harakat aniq odamga bog'langan."],
 ["Kim qachon smenaga kelgani va ketganini qayerda ko'rish mumkin?",["Сотрудник → Посещаемость","Финансы → Заработная плата","Аналитика → История","Сотрудник → Должности"],"«Сотрудник → Посещаемость» POS orqali kelish va ketish belgilarini ko'rsatadi. Bu ishlangan vaqtni hisoblashga yordam beradi."],
 ["«Устройства → Терминалы» da qanday qurilma turlari bor?",["Ish stoli, Ofitsiant, Kuryer, Mobil","Kassa, Printer, Skaner","Faqat kassa","Bek-ofis va KDS"],"Terminal turlari: Ish stoli (kassa), Ofitsiant, Kuryer, Mobil. Har birining o'z paroli bor."],
 ["Telefon, balans va cheklar soni bilan mehmonlar bazasi qayerda saqlanadi?",["Маркетинг → Клиенты","Продажи → Чеки","Сотрудник → Пользователи","Склад → Поставщики"],"Mehmonlar bazasi — «Маркетинг → Клиенты»: telefon, balans, tug'ilgan sana, cheklar, manba. Bu loyallik va kampaniyalar asosi."],
 ["«Маркетинг → Группа клиентов» nima uchun kerak?",["Mehmonlarni (masalan, «VIP mijoz») birlashtirish va ularga turli qoidalar belgilash","Xodimlarni birlashtirish","Omborlarni birlashtirish","Filiallarni birlashtirish"],"Mijozlar guruhlari mehmonlarni (masalan, «Вип клиент») birlashtiradi va ularga turli qoidalar, masalan boshqa keshbek stavkasi berish imkonini beradi."],
 ["Hozir sadoqat dasturining qaysi turi mavjud?",["Keshbek (bonus va chegirma — «tez orada»)","Faqat chegirma","Faqat bonuslar","Hech qanday"],"Hozir keshbek mavjud: stavka, guruhlar uchun qoidalar, limitlar. Bonus va chegirma dasturlari «tez orada» deb belgilangan."],
 ["Sadoqat dasturida nimani cheklash mumkin?",["Kunlik keshbek limiti va chekning keshbek bilan to'lanadigan ulushini","Ofitsiantlar sonini","Stollar sonini","Yetkazib berish narxini"],"Loyallikda kunlik keshbekni va mehmon keshbek bilan to'laydigan chek ulushini cheklash mumkin. Bu muassasani katta yo'qotishlardan himoya qiladi."],
 ["«Настройки → Автоматизация» nima qiladi?",["Triggerlar bo'yicha amallarni ishga tushiradi, masalan mijoz xarajatlari o'zgarganda","Narxlarni avtomatik o'zgartiradi","Xodimlarni avtomatik yollaydi","Zaxira nusxa oladi"],"Avtomatlashtirish triggerlar bo'yicha harakatlarni ishga tushiradi, masalan mehmon xarajatlari o'zgarganda. Bu mehmonlar bilan qo'l mehnatisiz ishlashga yordam beradi."],
 ["O'zbekistonda qaysi modullar cheklarni soliq idorasiga yuboradi?",["E-POS Systems, TINDA, QPOS","Yandex Eats, Uzum Tezkor","KDS, Stop-list","Hamyon, Sharhlar"],"O'zbekistonda fiskalizatsiya — bepul E-POS Systems, TINDA va QPOS modullari. Ular cheklarni E-Kassa operatorlari orqali Soliq'qa yuboradi."],
 ["«Aksizlarni kuzatish» moduli nima uchun?",["Aksiz tovarlarni hisobga olish va sotuvda aksiz kodini talab qilish","Restoran soliqlarini hisoblash","Ombor qoldiqlarini yuritish","Menyu chop etish"],"Aksizlarni kuzatish alkogol va tamaki sotishda kerak: kassa sotishda aksiz kodini talab qiladi."],
 ["Restoran telefon orqali ko'p buyurtma qabul qiladi.",["Markaziy buyurtma tizimi (15 $)","Tarozi","Hamyon","Aksizlar"],"Markaziy buyurtmalar tizimi (15 $) — telefon buyurtmalarini call-markaz kabi qayta ishlash uchun. Buyurtmalar adashmaydi va yo'qolmaydi."],
 ["Mehmonlar kassirsiz o'zlari buyurtma berishi kerak.",["O'z-o'ziga xizmat kioski","Davomat","Ochiq API","Motivatsiya dasturi"],"O'z-o'ziga xizmat kioski — bepul modul: mehmon buyurtmani o'zi rasmiylashtiradi. Navbat va kassirlar yetishmaganda yordam beradi."],
 ["«Mijoz ekrani» nima uchun?",["Mehmon kassadagi ikkinchi ekranda o'z buyurtmasini va QR-kodni ko'radi","Oshpaz buyurtmalarni ko'radi","Ega hisobotlarni ko'radi","Kuryer marshrutni ko'radi"],"Mijoz ekrani — kassadagi ikkinchi ekran: mehmon o'z buyurtmasi va QR-kodni ko'radi. Modul bepul."],
 ["«Tarozi» moduli nima uchun?",["Kassa tovar vaznini tarozidan o'zi oladi","Xodimlarni tortish uchun","Yetkazib berish vaznini hisoblash uchun","Qoldiqni tekshirish uchun"],"Tarozi moduli kassaga tovar vaznini avtomatik o'qish imkonini beradi. Vazn bilan sotiladigan tovarlar uchun foydali."],
 ["«Veb-kassir» (15 $) nima uchun?",["Kompaniyalarga sotish (ulgurji, korporativ buyurtmalar) alohida kassasiz","Kuryer uchun kassa","Mehmonlar uchun onlayn to'lov","Oshxona uchun kassa"],"Veb-kassir (15 $) — alohida kassasiz brauzer orqali kompaniyalarga sotish: ulgurji, korporativ buyurtmalar."],
 ["«Shtrix-kod generatori» nima uchun?",["Shtrix-kod, nom, narx va sanalar bilan yorliq chop etish","QR-menyuni skanerlash","Parol yaratish","Chek chop etish"],"Shtrix-kod generatori shtrix-kod, nom, narx va sanalar bilan etiketkalar chop etadi. Tovarlarda zavod shtrix-kodi bo'lmaganda foydali."],
 ["«Ochiq API» (10 $) nima?",["Tashqi dasturlarni maxfiy kalitlar orqali Clopos ma'lumotlariga ulash","Clopos'ning bepul versiyasi","Mehmonlar uchun mobil ilova","Yetkazib berish moduli"],"Ochiq API (10 $) tashqi dasturlarni Client ID va Client Secret maxfiy kalitlari orqali Clopos ma'lumotlariga ulaydi. Kalitlarni yozishmalarda yuborish mumkin emas."],
 ["Mijoz modullarni qayerda ko'radi va ulaydi?",["Модули → Все","Настройки → Общие","Устройства → Терминалы","Финансы → Счета"],"Modullar «Модули → Все» da ulanadi. U yerda «Сторонние приложения» yorlig'i ham bor — masalan, Telegram-bot."]
],
"exam-3": [
 ["Retention skriptining asosiy tamoyili:",["Biznes → CLOPOS → sabab → ehtiyoj → yechim → keyingi qadam","Salomlashish → taqdimot → sotuv","Muammo → chegirma → uzaytirish","Ro'yxatdagi savollar, chetga chiqmasdan"],"Skript tartibi: avval mijoz biznesi, keyin Clopos bilan holat, keyin haqiqiy sabab va ehtiyoj, shundan keyingina yechim va keyingi qadam. Taklifdan boshlansa, mijoz qo'ng'iroqni sotuv deb qabul qiladi."],
 ["Retention skripti — bu…",["Jonli suhbat uchun tuzilma va maslahatlar","So'zma-so'z o'qiladigan matn","Taqiqlangan mavzular ro'yxati","Texnik qo'llab-quvvatlash uchun yo'riqnoma"],"Skript tayyor matnni emas, suhbat tuzilmasini belgilaydi. Savollarni har bir mijozga moslab o'zingiz tuzasiz — shunda suhbat jonli eshitiladi."],
 ["Skriptning birinchi blokida nima aniqlanadi?",["Biznes holati: muassasa ishlayaptimi, format, mavsumiylik, ta'mir, savdo, xodimlar","Mijoz qarzi","Qaysi modullarni sotish","Dastur versiyasi"],"Birinchi blok — biznes: muassasa ishlayaptimi, format, mavsumiylik, ko'chish yoki ta'mir, savdo va xodimlar. Bu dastur haqida gaplashishdan oldin kontekstni tushunishga yordam beradi."],
 ["Skriptning ikkinchi blokida nima aniqlanadi?",["Mijoz Clopos'dan foydalanadimi, hammasi ishlayaptimi, qaysi funksiyalar ishlatiladi, qiyinchiliklar bormi","Muassasada nechta xodim bor","Mijozning raqobatchilari kim","Mijoz yangi nuqtani qachon ochadi"],"Ikkinchi blok — Clopos bilan holat: foydalanishadimi, hammasi ishlayaptimi, qaysi funksiyalar, qiyinchiliklar bormi. Shunda xavf qayerda va qayerda yordam berish mumkinligi ko'rinadi."],
 ["Mijoz faol emas. Skript qanday sabablarni sanaydi?",["Mavsumiylik, yopilish, ta'mir, xodimlar, Wi-Fi, texnik muammolar, narx, boshqa dastur, savdo pasayishi","Faqat texnik xatolar","Faqat yuqori narx","Faqat yomon internet"],"Skript sabablarni sanab beradi: mavsumiylik, yopilish, ta'mir, xodimlar, Wi-Fi, texnik muammolar, narx, boshqa dastur, savdo pasayishi. Muhimi — birinchi aytilganini emas, haqiqiysini topish."],
 ["Skript bo'yicha suhbat qanday olib boriladi?",["Bahslashmaslik, savollarni mexanik bermaslik: aniqlash → tushunish → yechim taklif qilish","Har bir shikoyatga e'tiroz bildirish","Qat'iy savollar tartibida","Mijozdan ko'proq gapirish"],"Bahslashmaslik va savollarni mexanik bermaslik: aniqlash, tushunish, yechim taklif qilish. Bahs mijozni uzoqlashtiradi."],
 ["Skript bo'yicha qaysi variant aniq kelishuv?",["Payshanba kuni ega bilan bog'lanib, o'chirishlar hisobotini ko'rsatish","Mijoz o'ylab ko'radi","Qachondir gaplashamiz","Biror narsa bo'lsa — yozing"],"Kelishuv aniq bo'lishi kerak: kim, nima va qachon qiladi. «Qachondir gaplasharmiz» odatda hech narsa bilan tugamaydi."],
 ["Qo'ng'iroqdan keyin CRM'ga nima yozilishi shart?",["Biznes holati, faolsizlik sababi, muammo yoki ehtiyoj, kelishuvlar, keyingi harakatlar, keyingi aloqa sanasi","Faqat qo'ng'iroq natijasi","Faqat mijoz telefoni","Qo'ng'iroq qisqa bo'lsa, hech narsa"],"CRM'ga biznes holati, nofaollik sababi, muammo yoki ehtiyoj, kelishuvlar, keyingi harakatlar va keyingi aloqa sanasi yoziladi. Shunda istalgan hamkasb nima bo'layotganini tushunadi."],
 ["Qo'ng'iroq CRM'ga yozilmagan. Bu qanday baholanadi?",["Vazifa bajarilmagan hisoblanadi","Mijoz rozi bo'lsa, normal","KPI'ga plyus","Hech qanday"],"Reglament bo'yicha CRM'ga yozilmagan muloqot — suhbat yaxshi o'tgan bo'lsa ham, bajarilmagan vazifa."],
 ["Qo'ng'iroqlar qanday ro'yxatlar bo'yicha qilinadi?",["Tasdiqlangan ro'yxatlar bo'yicha","O'z tanlovingiz bo'yicha","Faqat kiruvchilar","Sotuv ro'yxati bo'yicha"],"Qo'ng'iroqlar xodim tanlovi bo'yicha emas, tasdiqlangan ro'yxatlar bo'yicha qilinadi. Shunda hech bir mijoz e'tiborsiz qolmaydi."],
 ["Mijozga nechta mas'ul xodim biriktiriladi?",["Bitta","Ikkita","Butun bo'lim","Hech kim"],"Mijozga bitta mas'ul biriktiriladi. Bu mijozga turli odamlar qo'ng'iroq qilib, hech kim butun tarixni bilmaydigan holatni istisno qiladi."],
 ["O'z mijozingizni hamkasbga topshirish mumkinmi?",["Faqat bo'lim rahbari roziligi bilan","Ha, istalgan vaqtda","Yo'q, hech qachon","Faqat mijoz so'rasa"],"Mijozni hamkasbga faqat bo'lim rahbari roziligi bilan topshirish mumkin. O'zboshimchalik bilan topshirish reglamentni buzadi."],
 ["Rahbar mijoz holatini so'ramoqda. Nima qilish kerak?",["Darhol dolzarb ma'lumot berish: tarix, holat, muammolar, vazifalar","Esingizda yo'qligini aytish","Oy oxirigacha kutishni so'rash","Mijozga yuborish"],"Mas'ul mijozning tarixi, statusi, muammolari va vazifalarini bilishi va rahbar so'roviga darhol taqdim etishi shart."],
 ["Reglamentga ko'ra texnik muammo qanday topshiriladi?",["Faqat texnik qo'llab-quvvatlashga va faqat CRM orqali: mohiyati, vaqti, aniqlovchi savollar, mijoz izohlari","Hamkasbga og'zaki","Mijoz qo'llab-quvvatlashga o'zi yozadi","Dasturchiga shaxsiy messenjerda"],"Texnik muammo faqat texnik qo'llab-quvvatlashga va faqat CRM orqali — mohiyati, vaqti, aniqlashtirishlar va mijoz izohlari bilan topshiriladi."],
 ["Retention xodimi murakkab texnik ko'rsatmalar bera oladimi?",["Yo'q: mutaxassis talab qiladigan ko'rsatmalarni texnik qo'llab-quvvatlash beradi; asosiy funksiyalarni ko'rsatish va mini-o'quv mumkin","Ha, istalganini","Ha, mijoz so'rasa","Faqat dam olish kunlari"],"Retention xodimi texnik mutaxassis talab qiladigan ko'rsatmalar bermaydi: mijoz tizimiga zarar yetkazishi mumkin. Oddiy maslahatlar berish mumkin."],
 ["Texnik vazifa bo'yicha mijoz bilan muloqotni kim nazorat qiladi?",["Retention xodimi — keys to'liq yopilgunga qadar","Faqat texnik qo'llab-quvvatlash","Mijozning o'zi","Hech kim"],"Texnik qo'llab-quvvatlash muammoni hal qilayotganda mijoz bilan muloqotni Retention xodimi keys to'liq yopilgunga qadar olib boradi."],
 ["Retention xodimi mijozlarga nima taklif qilishi mumkin?",["Modullar, integratsiyalar, avtomatlashtirish tizimlari, uskunalar, qaytarish takliflari va tavsiyalar","Faqat chegirmalar","Faqat uzaytirish","Hech narsa"],"Retention tasdiqlangan shartlar doirasida modullar, integratsiyalar, avtomatlashtirish tizimlari, uskuna, qaytarish takliflari va tavsiyalarni taklif qilishi mumkin."],
 ["Mijoz chegirma yoki alohida shartlar so'ramoqda.",["Rahbarga mijoz haqida to'liq ma'lumot berib, shartlarni kelishish","Chegirmani o'zingiz berish","Avval va'da qilib, keyin kelishish","Rad etish"],"Chegirma va maxsus shartlarni rahbar kelishadi. Xodim unga mijoz haqida to'liq ma'lumot beradi va mijozga javobni aytadi."],
 ["Quyidagilardan qaysi biri reglamentda taqiqlangan?",["Kompaniya bilan kelishilmagan va'dalar berish","Mini-o'quv o'tkazish","Modullar taklif qilish","Vazifalarni texnik qo'llab-quvvatlashga topshirish"],"Reglament kelishilmagan va'dalar, rahbarsiz chegirmalar, tekshirilmagan ma'lumot, murojaatlarni e'tiborsiz qoldirish va murakkab texnik ko'rsatmalarni taqiqlaydi."],
 ["Mijoz bilan muloqot qanday bo'lishi kerak?",["Xushmuomala, xotirjam, tushunarli, professional","Har qanday holatda tez","Norasmiy","Faqat yozma"],"Muloqot standarti: xushmuomala, xotirjam, tushunarli, professional. Standartni buzish reglament buzilishi hisoblanadi."],
 ["Mijoz bilan nizoli vaziyat. Nima qilish kerak?",["Bo'lim rahbariga eskalatsiya qilish","Oxirigacha bahslashish","Javob bermay qo'yish","Sales'ga topshirish"],"Nizoli va murakkab vaziyatlar bo'lim rahbariga eskalatsiya qilinadi. Bu ham mijozni, ham xodimni himoya qiladi."],
 ["Ish vaqti qanday hisobga olinadi?",["Smena boshida va oxirida Face ID orqali","Daftarga yozib","Birinchi qo'ng'iroq bo'yicha","Hisobga olinmaydi"],"Ish vaqti smena boshida va oxirida Face ID belgisi bilan qayd etiladi."],
 ["Hamkasb bilan smenani o'zingiz almashtirsangiz bo'ladimi?",["Yo'q, jadvalni o'zboshimchalik bilan o'zgartirish mumkin emas","Ha, kelishsangiz","Ha, oyiga bir marta","Ha, mijozlar kam bo'lsa"],"Jadvalni o'zboshimchalik bilan o'zgartirish yoki smenalarni almashish mumkin emas — faqat rahbar orqali."],
 ["Kuniga suhbatlarning minimal umumiy vaqti qancha?",["1 soat; kam bo'lsa — 30 000 so'm jarima","30 daqiqa","2 soat","Belgilanmagan"],"Kuniga kamida 1 soat suhbat. Kam bo'lsa — reglament bo'yicha 30 000 so'm jarima."],
 ["Reglamentga ko'ra quyidagilardan qaysi biri kundalik vazifa?",["Inactive Clients faylini yuritish, yangilash va undagi mijozlarga qo'ng'iroq qilish","Mijozlarda inventarizatsiya o'tkazish","Clopos serverini sozlash","Ijtimoiy tarmoqlarga post yozish"],"Har kuni xodim Inactive Clients faylini yuritadi, yangilaydi va undagi mijozlarga qo'ng'iroq qiladi. Buxgalteriya va uskuna ta'miri — bizning vazifamiz emas."],
 ["Sotuv bo'limi (Sales) mijoz holatini aniqlashni so'ramoqda. Retention nima qiladi?",["Sales vazifasi bo'yicha mijozga qo'ng'iroq qiladi, holatni aniqlaydi va natijani CRM'ga yozadi","Rad etadi — bu Retention vazifasi emas","Vazifani texnik qo'llab-quvvatlashga topshiradi","Mijoz o'zi qo'ng'iroq qilishini kutadi"],"Retention sotuv bo'limi vazifalari bo'yicha ham chiquvchi qo'ng'iroqlar qiladi: masalan, mijoz statusini aniqlab, Sales'ga qaytaradi."],
 ["Retention mijozlarga har kuni qaysi masalalarda maslahat beradi?",["Soliq, Telegram va boshqa ish masalalari bo'yicha","Faqat narxlar bo'yicha","Soliq sxemalari bo'yicha","Xodim yollash bo'yicha"],"Retention har kuni mijozlarga Soliq, Telegram va boshqa ish masalalari bo'yicha maslahat beradi."],
 ["Retention xodimining KPI'siga nima kiradi?",["Aloqalar, ushlab qolingan va qaytarilgan mijozlar, yopilgan texnik keyslar, CRM sifati","Faqat restoranlar tushumi","Chatdagi xabarlar soni","Tushlik vaqti"],"KPI: aloqalar soni, ushlab qolingan va qaytarilgan mijozlar, churn kamayishi, topshirilgan va yopilgan texnik keyslar, CRM sifati. Restoranlar tushumi KPI'ga kirmaydi."],
 ["Quyidagilardan qaysi biri reglament buzilishi hisoblanadi?",["Texnik muammoni o'z vaqtida topshirmaslik","Mijozga mini-o'quv o'tkazish","Tasdiqlangan ro'yxat bo'yicha qo'ng'iroq","Kelishuvlarni CRM'ga yozish"],"Texnik muammoni kech topshirish — buzilish: mijoz uzoqroq qiynaladi va ketish xavfi oshadi."],
 ["Mijoz bilan birinchi MBR qachon o'tkaziladi?",["Birinchi ish smenasidan 30 kun o'tib","To'lov kuni","Bir yildan keyin","O'tkazilmaydi"],"Birinchi MBR birinchi ish smenasidan 30 kun keyin o'tkaziladi. Undan oldin — 3, 7 va 14-kunlardagi nazorat nuqtalari."],
 ["MBR'da nima muhokama qilinadi?",["Tizimdan foydalanish, muassasa uchun natija, kuzatuv sifati va oy uchun 2–3 ta harakat","Faqat shartnomani uzaytirish","Faqat shikoyatlar","Faqat yangi modullar"],"MBR'da tizimdan foydalanish, muassasa uchun natija, kuzatuv sifati va keyingi oy uchun 2–3 harakat muhokama qilinadi."],
 ["Mijoz ulanish bosqichida «tiqilib qoldi»: xodimlar o'zlari ishlamaydi. Retention uchun bu nimani anglatadi?",["Bu ketish xavfi — yordam va o'qitish kerak","Hammasi joyida","Bu faqat Sales vazifasi","Mijozni uzish kerak"],"Xodimlar mustaqil ishlamasa, onbording yakunlanmagan va mijoz xavf ostida. Sababni aniqlab, yordam berish kerak: o'qitish, rollarni sozlash."],
 ["Mijoz: «Qimmat, voz kechmoqchimiz». Birinchi qadam?",["«Qimmat» ortida nima turganini aniqlash: nimadan foydalanadi, qanday foyda ko'radi, nima bilan solishtiradi","30% chegirma","Raqobatchilar qimmatroq deyish","Voz kechishni rasmiylashtirish"],"«Qimmat» ortida odatda «foydasini ko'rmayapman» turadi. Avval nimadan foydalanishlari va nima bilan solishtirishlarini aniqlang, keyin qadrini ko'rsating. Chegirma va'da qilmang."],
 ["Kassadan foydalanishadi, lekin 3 hafta hisobotlarni ochishmagan.",["Xavf signali: egaga hisobotlarni yoki AI-assistentni ko'rsatish","Hammasi yaxshi","Tizim xatosi","Bizning sohamiz emas"],"Hisobotlar haftalab ochilmasa, ega tizim foydasini ko'rmaydi — bu xavf signali. Uning vazifalariga mos hisobotlarni ko'rsatish kerak."],
 ["Mijoz kamroq soliq to'lash bo'yicha maslahat so'ramoqda.",["Maslahat bermaslik, buxgalterga yo'naltirish, Clopos'dan ma'lumot yuklab olishga yordam berish","Sxema berish","Cheklarni yubormaslikni maslahat berish","Qo'ng'iroqni tugatish"],"Soliq maslahatlari — bizning vakolatimiz emas. Noto'g'ri maslahat mijozga zarar keltirishi mumkin, shuning uchun buxgalterga yo'naltiramiz."],
 ["Ofitsiantlar dasturdan foydalanishni xohlamaydi.",["Sababini aniqlash, o'qitish, rollar va menyu maketini sozlash, jamoada mas'ul tayinlash","Bu ularning muammosi","Xodimlarni almashtirish","Ofitsiant terminalini o'chirish"],"Ko'pincha ofitsiantlar noqulaylik yoki tushunmaslik tufayli dasturdan foydalanmaydi. O'qitish, rollar va qulay maket muammoni hal qiladi."],
 ["Ega: «Sizning dasturingiz bilan tushum kamaydi!»",["Tushumni birga cheklar va o'rtacha chekka ajratish, kun va soatlarni topish; texnik muammoni biznes muammosidan ajratish","Bahslashish","Chegirma berish","Qo'llab-quvvatlashga topshirib, unutish"],"Tushumni birga cheklar va o'rtacha chekka ajrating. Shunda nima o'zgargani ko'rinadi va suhbat ayblovlardan yechimga o'tadi."],
 ["Mijoz siz takrorlay olmaydigan xatoni tasvirlamoqda.",["Tafsilotlarni yig'ish, CRM orqali topshirish, faqat tasdiqlangan muddatni aytish","Xato yo'qligini aytish","Bugun tuzatishni va'da qilish","Hammasini qayta o'rnatishni so'rash"],"Xatoni takrorlab bo'lmasa ham, tafsilotlar texnik qo'llab-quvvatlashga yordam beradi. CRM orqali topshiring va mijozni xabardor qilib turing."],
 ["Mijoz: «Hisobot katta zarar ko'rsatyapti, dastur noto'g'ri hisoblaydi».",["Texkartalar va ingredientlar birligini tekshirish, sababini ko'rsatish va birga tuzatish","Bu xato ekaniga rozi bo'lish","Hisobotlarga qaramaslikni maslahat berish","Sotuvga topshirish"],"Ulkan minus deyarli doim ma'lumotlar bilan bog'liq: texkartalar, birliklar, hujjatlar. Sababni mijoz ma'lumotlarida ko'rsating va tuzatishga yordam bering."],
 ["Expired mijoz: «Ta'mirdamiz, keyin ko'ramiz».",["Ta'mir muddati va rejalarni aniqlash, sababni yozish va ochilishga qo'ng'iroq qilishni kelishish","«Rad etdi» deb yozib, yopish","Yangi modul taklif qilish","Boshqa qo'ng'iroq qilmaslik"],"Ta'mir muddati va rejalarni aniqlang, sababni yozing va keyingi qo'ng'iroq sanasini kelishing. Ta'mirdan keyin ishga tushirishda yordam taklif qiling."],
 ["Mijoz ishlamay qo'ydi: «Internet doim uzilib qolyapti».",["Tafsilotlarni aniqlash, texnik qismini CRM orqali topshirish, yechimni nazorat qilish va ishga qaytishga yordam berish","Dasturni almashtirishni maslahat berish","Bu bizning muammomiz emas deyish","Chegirma taklif qilish"],"Muammo tafsilotlarini aniqlang va texnik qismini CRM orqali topshiring. Mijozni hal bo'lguncha o'zingiz olib boring."],
 ["Mijoz tejash uchun 3 ta modulni o'chirmoqchi.",["Ulardan foydalanilayotganini aniqlash; foydasini ko'rsatish, keraksizlarini esa halol o'chirib, mijozni saqlab qolish","Har qanday holatda qaytarish","Suhbatsiz darhol o'chirish","Shartnomani bekor qilish bilan qo'rqitish"],"Modullar ishlatiladimi, aniqlang. Keraksizlarini halol o'chiring — Contraction Churn'dan yaxshi. Foydalilarini sozlashga yordam bering."],
 ["Mamnun mijoz ikkinchi filial ochmoqda.",["Clopos'da ishga tushirishni rejalashtirishga yordam berish va reglament bo'yicha mas'ulni jalb qilish","Tabriklab, tugatish","Darhol hisob yuborish","Kutishni maslahat berish"],"Yangi filial — bu Expansion. Clopos'da ishga tushirishni rejalashtirishga va yangi nuqtaga kerakli modullarni ulashga yordam bering."],
 ["Mijoz Clopos'ni raqobatchi bilan solishtirib, ketishini aytmoqda.",["Sababni va raqobatchi nimani va'da qilayotganini aniqlash; muammoni hal qilish yoki eskalatsiya qilish","Raqobatchini tanqid qilish","Istalgan funksiyani va'da qilish","Darhol qo'yib yuborish"],"Sababni va raqobatchi nimani va'da qilayotganini biling. Uni tanqid qilmang. Muammoni hal qiling yoki rahbarga eskalatsiya qiling."],
 ["Mijoz Clopos'da yo'q funksiyani so'ramoqda.",["Halol aytish, so'rovni fidbek sifatida yozish, muqobil yo'l taklif qilish","Tez orada bo'lishini va'da qilish","«Mumkin emas» deb tugatish","Boshqa dasturni tavsiya qilish"],"Funksiya yo'qligini halol ayting, so'rovni fikr-mulohaza sifatida yozing va hozir nima bilan almashtirish mumkinligini taklif qiling. Ishlab chiqishni va'da qilish mumkin emas."],
 ["Restoran kuniga 30 ta Yandex Eats buyurtmasini oladi va ularni qo'lda kiritadi.",["Bu qancha vaqt va xatoga tushayotganini ko'rsatib, Yandex Eats modulini taklif qilish","Hech narsa taklif qilmaslik","Yetkazib berishni yopishni taklif qilish","Tarozi taklif qilish"],"Qo'lda kiritish qancha vaqt va xatoga tushishini ko'rsating va Yandex Eats modulini taklif qiling. Natijani bir-ikki haftadan keyin tekshirishni kelishing."],
 ["Mehmonlar qaytmayapti. Clopos qanday yordam beradi?",["Mijozlar bazasi, keshbek, kampaniyalar, sharhlar — va tizimdan tashqari maslahatlar: xaritalar, ijtimoiy tarmoqlar","Hech qanday","Tarozi moduli","Ombor ko'chirishlari"],"Mehmonlarni qaytarish uchun Clopos'da mijozlar, keshbek, kampaniyalar va sharhlar bor. Bundan tashqari Clopos'dan tashqari maslahatlar: ijtimoiy tarmoqlar, xaritalar, servis."],
 ["Kassir «o'zinikilarga» chegirma beradi.",["Huquqlarni cheklash, xodim bo'yicha tarix va chegirmalarni ko'rish, pozitsiyalarga chegirmani taqiqlash","Kassirni bo'shatish","Hammaga chegirmani o'chirish","Hech narsa"],"Chegirma huquqlarini cheklash, tarix va xodimlar bo'yicha chegirmalarni ko'rishni taklif qiling. Ayblamang — ma'lumotlarni ko'rsating, xulosani ega chiqaradi."],
 ["Chek-list bo'yicha mijozda yuqori ketish xavfi bor.",["1–2 kun ichida bog'lanish, mijoz raqamlari asosida foyda haqida suhbat tayyorlash, rahbarni jalb qilish","Bir oy kutish","Xat yuborish","Qimmatroq tarif taklif qilish"],"Yuqori xavf tez munosabatni talab qiladi: 1–2 kun ichida bog'lanish va xavf sabablari bo'yicha suhbat tayyorlash."],
 ["Mijoz norozi, muammo hali hal bo'lmagan. Suhbatni qanday tugatish kerak?",["Muammoni tan olish, harakatlar va keyingi aloqa sanasini aytish, CRM'ga yozish","«Imkon qadar tez» hal qilishni va'da qilish","Kechirim so'rab, telefonni qo'yish","Tushuntirishsiz boshqa xodimga o'tkazish"],"Muammoni tan oling, keyingi qadam va tasdiqlangan muddatni ayting, CRM'ga yozing va qayta qo'ng'iroq qiling. Mijoz masala unutilmaganini bilishi kerak."]
]
});
